import{_ as i,a0 as n,w as s,s as u,ao as a,I as p,x as o,a1 as r,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const E=JSON.parse('{"title":"谷歌使用 Duality 主导的完全同态开源加密库 | LCTT x X-CMD","titleTemplate":false,"description":"谷歌使用 Duality 主导的完全同态开源加密库 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"谷歌使用 Duality 主导的完全同态开源加密库 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"谷歌使用 Duality 主导的完全同态开源加密库 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220914 Google Uses Fully Homomorphic Open Source Duality-Led Encryption Library","title":"谷歌使用 Duality 主导的完全同态开源加密库","tag":"202209","desc":""},"relativePath":"202209/20220914 Google Uses Fully Homomorphic Open Source Duality-Led Encryption Library.md","filePath":"[post].md"}'),y={name:"202209/20220914 Google Uses Fully Homomorphic Open Source Duality-Led Encryption Library.md"};function d(m,t,f,T,g,D){const e=n("Link");return s(),u("div",null,[t[15]||(t[15]=a('<h1 id="谷歌使用-duality-主导的完全同态开源加密库" tabindex="-1">谷歌使用 Duality 主导的完全同态开源加密库 <a class="header-anchor" href="#谷歌使用-duality-主导的完全同态开源加密库" aria-label="Permalink to “谷歌使用 Duality 主导的完全同态开源加密库”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/09/google-3-1536x1123.jpg" alt=""></p><blockquote><p>合作伙伴关系的增长加速了 FHE 市场的采用。</p></blockquote><p>据 Duality 技术公司的新闻稿，谷歌已将其在 GitHub 上开源的使用 XLS SDK 开发的开源项目完全同态加密（FHE）转译器与领先的开源<ruby>完全同态加密<rt>fully homomorphic encryption</rt></ruby>库 OpenFHE 合并。通过使加密知识更简单、更容易接近，开发者对 FHE 的采用将增加。</p><p>这类称为 FHE 的加密技术不同于更常见的加密技术，因为它可以直接对加密数据进行计算，而无需密钥。一个由知名密码学家组成的社区创建了 OpenFHE，这是一个根深于后量子开源晶格密码学的加密库。</p><p>该库旨在实现最佳可用性、增强的 API、模块化、跨平台可移植性，以及与硬件结合时的项目加速器。开发人员可以通过将 OpenFHE 与谷歌的转译器结合起来，使用高级代码来操作加密数据，例如经常用于未加密数据的 C++，而不需要学习密码学。</p><p>谷歌的转译器简化了使用 FHE 驱动的应用程序的过程，而无需目前从头开始构建 FHE 所需的广泛的软件开发专业知识。这填补了软件设计人员和开发人员偶尔遇到的空白，他们希望从 FHE 的功能中受益，而不必经历那具有挑战性的学习曲线。</p><p>Duality 公司的密码学研究高级主管兼首席科学家 Yuriy Polyakov 补充说：“我们的团队通过我们的 OpenFHE 库达成了重要的里程碑，它已迅速成为当今许多技术领导者的选择，例如谷歌。谷歌转译器为那些非 FHE 专家的应用开发者社区提供了 OpenFHE 同态加密的最新技术。”</p><hr>',9)),p("p",null,[t[1]||(t[1]=o("via: ",-1)),r(e,{href:"https://www.opensourceforu.com/2022/09/google-uses-fully-homomorphic-open-source-duality-led-encryption-library/"},{default:l(()=>[...t[0]||(t[0]=[o("https://www.opensourceforu.com/2022/09/google-uses-fully-homomorphic-open-source-duality-led-encryption-library/",-1)])]),_:1})]),p("p",null,[t[6]||(t[6]=o("作者：",-1)),r(e,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:l(()=>[...t[2]||(t[2]=[o("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=o(" 选题：",-1)),r(e,{href:"https://github.com/lkxed"},{default:l(()=>[...t[3]||(t[3]=[o("lkxed",-1)])]),_:1}),t[8]||(t[8]=o(" 译者：",-1)),r(e,{href:"https://github.com/littlebirdnest"},{default:l(()=>[...t[4]||(t[4]=[o("littlebirdnest",-1)])]),_:1}),t[9]||(t[9]=o(" 校对：",-1)),r(e,{href:"https://github.com/wxy"},{default:l(()=>[...t[5]||(t[5]=[o("wxy",-1)])]),_:1})]),p("p",null,[t[12]||(t[12]=o("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[10]||(t[10]=[o("LCTT",-1)])]),_:1}),t[13]||(t[13]=o(" 原创编译，",-1)),r(e,{href:"https://linux.cn/"},{default:l(()=>[...t[11]||(t[11]=[o("Linux中国",-1)])]),_:1}),t[14]||(t[14]=o(" 荣誉推出",-1))])])}const H=i(y,[["render",d]]);export{E as __pageData,H as default};
